  | { kind: 'square'; side: number };

function assertNever(value: never): never {
  throw new Error(`cas non géré: ${JSON.stringify(value)}`);
}

function area(shape: Shape): number {
  // TODO : switch sur shape.kind : cercle = PI x rayon², rectangle = largeur x hauteur, carré = côté² ;
  //        termine par `default: return assertNever(shape);`
  return 0;
}

const labels: Record<Shape['kind'], string> = { circle: 'cercle', rectangle: 'rectangle', square: 'carré' };
const shapes: Shape[] = [
  { kind: 'circle', radius: 5 },
  { kind: 'rectangle', width: 3, height: 4 },
  { kind: 'square', side: 2 },
];
for (const shape of shapes) {
  console.log(`${labels[shape.kind]}: ${area(shape).toFixed(2)}`);
}

quiz.prompt:
Trouve le défaut de modélisation :
```ts
interface Shape {
  kind: string;
  radius?: number;
  width?: number;
  height?: number;
}
```

Prédis le résultat :
```ts
function f(x: string | number) {
  if (typeof x === 'string') return x.toUpperCase();
  return x.toFixed(1);
}
console.log(f('ab'), f(2));
```
